insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_48_v1'
from (values
('127.263.d.1.A',3,'A team of cashiers keeps a line moving by covering for each other during a rush. This shows:','["Effective teamwork", "Customer neglect", "Inventory shrink", "Poor planning"]'::jsonb,0,'Cooperation keeps service steady.','original'),
('127.263.d.1.A',4,'A new hire disagrees with a coworker about shelf stocking. The best interpersonal approach is to:','["Ignore the coworker", "Discuss it calmly and seek a shared solution", "Complain to customers", "Redo the work secretly"]'::jsonb,1,'Calm discussion resolves conflict.','original'),
('127.263.d.1.B',3,'A self-development plan for a shift leader might include setting goals to improve:','["Store lighting", "Parking spots", "Communication and delegation", "Price tags"]'::jsonb,2,'Leadership skills grow with goals.','original'),
('127.263.d.1.B',4,'A good self-development goal is specific and has:','["Unlimited scope", "No end date", "No measurement", "A deadline and a way to measure progress"]'::jsonb,3,'SMART goals.','original'),
('127.263.d.1.C',3,'Employers in retail value employability skills such as dependability and:','["Willingness to learn", "Poor attitude", "Careless counts", "Late arrival"]'::jsonb,0,'Employers want learners.','original'),
('127.263.d.1.C',4,'Arriving on time, following dress code, and completing tasks are examples of:','["Marketing tools", "Professional work habits", "Optional choices", "Pricing methods"]'::jsonb,1,'Habits show employability.','original'),
('127.263.d.2.A',3,'Good communication with a customer starts with:','["Interrupting", "Talking over them", "Listening to what they need", "Looking away"]'::jsonb,2,'Listening first.','original'),
('127.263.d.2.A',4,'An associate who repeats back a customer''s request before acting is practicing:','["Sales pressure", "Distraction", "Guessing", "Active listening"]'::jsonb,3,'Confirms understanding.','original'),
('127.263.d.2.B',3,'A thank-you email to a customer who bought furniture is an example of:','["Written business communication", "Verbal communication only", "Nonverbal communication", "Face-to-face only"]'::jsonb,0,'Email is written.','original'),
('127.263.d.2.B',4,'A formal letter to a vendor should include a greeting, a clear purpose, and:','["Emojis only", "A courteous closing", "Slang", "No signature"]'::jsonb,1,'Professional format.','original'),
('127.263.d.2.C',3,'A store''s return policy affects an employee''s interactions with customers because the employee must:','["Change it each day", "Ignore the policy", "Apply the policy consistently", "Hide it"]'::jsonb,2,'Policies guide responses.','original'),
('127.263.d.2.C',4,'A customer asks for a refund outside the return window. The associate should:','["Give the refund secretly", "Walk away", "Argue", "Explain the policy politely and offer options"]'::jsonb,3,'Respectful and informative.','original'),
('127.263.d.2.D',3,'An associate''s cheerful attitude usually leads to a customer experience that is:','["More positive", "More confusing", "More expensive", "Shorter in all cases"]'::jsonb,0,'Attitude is contagious.','original'),
('127.263.d.2.D',4,'A negative attitude at the register can cause customers to:','["Praise the store", "Shop elsewhere next time", "Tell friends to visit", "Spend more"]'::jsonb,1,'Attitude affects loyalty.','original'),
('127.263.d.3.A',3,'A professional portfolio for a job search often contains a resume, samples of work, and:','["Photos of pets", "Game scores", "Letters of recommendation", "Receipts"]'::jsonb,2,'Shows qualifications.','original'),
('127.263.d.3.A',4,'A resume should be tailored to a job by highlighting:','["Every hobby", "Irrelevant details", "Salary history", "Skills that match the posting"]'::jsonb,3,'Relevance.','original'),
('127.263.d.3.B',3,'A letter of intent tells an employer that you are:','["Interested in the position and why you qualify", "Late", "Asking for a raise", "Quitting"]'::jsonb,0,'Shows interest.','original'),
('127.263.d.3.C',3,'When completing a job application, you should write:','["Rough guesses", "Accurate, legible information", "Blank answers", "Funny remarks"]'::jsonb,1,'Accuracy counts.','original'),
('127.263.d.3.C',4,'An application with several sections left blank may suggest to an employer that the applicant:','["Is highly organized", "Is a friend", "Lacks attention to detail", "Is overqualified"]'::jsonb,2,'Incomplete forms look careless.','original'),
('127.263.d.3.D',4,'Good references for a first retail job might include:','["Your landlord''s pet", "A random customer", "A competitor", "A former teacher or supervisor"]'::jsonb,3,'Choose reliable people.','original'),
('127.263.d.4.A',3,'The effectiveness of selling through a website can be evaluated by tracking:','["Conversion rates and returns", "Weather", "Parking use", "Gas prices"]'::jsonb,0,'Metrics show performance.','original'),
('127.263.d.4.A',4,'A retailer compares sales per marketing dollar across online and in-store channels to judge:','["Employee ages", "Which channel is more effective", "Store color", "Hours worked"]'::jsonb,1,'Return on spend.','original'),
('127.263.d.4.B',3,'A disadvantage of non-store retailing such as shopping online is that customers cannot:','["Shop at night", "Read reviews", "Touch or try the product first", "Compare prices"]'::jsonb,2,'No physical contact.','original'),
('127.263.d.4.B',4,'Shipping costs and delays are disadvantages of selling:','["Only at kiosks", "To neighbors only", "In person only", "Through non-store channels"]'::jsonb,3,'Delivery adds cost and wait.','original'),
('127.263.d.4.C',3,'An advantage of non-store retailing is access to:','["Shoppers at any hour", "Only daytime buyers", "A limited catalog", "Only local buyers"]'::jsonb,0,'Online is always open.','original'),
('127.263.d.4.C',4,'A non-store retailer can offer an almost unlimited catalog because it does not need:','["Customers", "Physical shelf space for every item", "Advertising", "Prices"]'::jsonb,1,'No shelf limits.','original'),
('127.263.d.5.A',3,'A retailer synthesizing survey and interview data is trying to find:','["The score of a game", "The hours of sunrise", "Patterns in what customers want", "A cure for the flu"]'::jsonb,2,'Synthesis finds patterns.','original'),
('127.263.d.5.A',4,'Comments from a focus group are examples of:','["Quantitative only", "Shipping data", "Payroll data", "Qualitative data"]'::jsonb,3,'Opinions are qualitative.','original'),
('127.263.d.5.B',3,'Data reports are used in retail to:','["Make decisions to improve the business", "Hide losses", "Replace staff", "Decorate walls"]'::jsonb,0,'Data drives decisions.','original'),
('127.263.d.5.B',4,'A report showing that 40% of returns come from one brand would lead a buyer to:','["Raise wages", "Review that vendor''s quality", "Order more without review", "Close the store"]'::jsonb,1,'Return data flags problems.','original'),
('127.263.d.5.C',3,'A well-designed survey question should be:','["Leading", "Confusing", "Clear and unbiased", "Very long"]'::jsonb,2,'Good wording avoids bias.','original'),
('127.263.d.5.C',4,'The question ''Don''t you agree our great service is the best?'' is a poor survey question because it is:','["Neutral", "Too short", "Open ended", "Leading"]'::jsonb,3,'It pushes the answer.','original'),
('127.263.d.5.D',3,'Disaggregating sales data means breaking totals down by:','["Categories such as product or day", "Nothing", "Staff names only", "Colors of walls"]'::jsonb,0,'Breaking apart reveals detail.','original'),
('127.263.d.5.D',4,'Total sales of $10,000 split into $6,000 weekdays and $4,000 weekends shows what share on weekends?','["60%", "40%", "4%", "10%"]'::jsonb,1,'4,000/10,000.','original'),
('127.263.d.5.E',3,'Breaking marketing data down by age, gender, or location helps a retailer:','["Increase confusion", "Ignore customers", "Target customers more precisely", "Reduce data"]'::jsonb,2,'Segmentation guides marketing.','original'),
('127.263.d.5.E',4,'If most online orders come from ages 18 to 24, the retailer might emphasize ads on:','["Local newspapers only", "Radio only", "Telephone books", "Platforms popular with young adults"]'::jsonb,3,'Match media to audience.','original'),
('127.263.d.5.F',3,'Product, price, promotion, and placement together are the:','["Marketing mix", "Tax code", "Store layout", "Inventory system"]'::jsonb,0,'The four Ps.','original'),
('127.263.d.5.F',4,'Raising the price of a product while also reducing its promotion most likely affects:','["Employee dress code", "Sales volume", "Store lighting", "Parking"]'::jsonb,1,'Mix elements interact.','original'),
('127.263.d.6.A',3,'Staple merchandise is stock that customers buy:','["Only on holidays", "Only once", "Regularly throughout the year", "Rarely"]'::jsonb,2,'Staples sell steadily.','original'),
('127.263.d.6.A',4,'Fashion merchandise differs from staple merchandise because it:','["Is always cheap", "Never changes", "Sells equally all year", "Changes with trends and has shorter selling periods"]'::jsonb,3,'Trend items are time-sensitive.','original'),
('127.263.d.6.B',3,'A merchandise plan includes planned sales, planned stock, planned reductions, and:','["Planned purchases", "Planned layoffs", "Planned vacations", "Planned holidays"]'::jsonb,0,'The plan''s components.','original'),
('127.263.d.6.B',4,'Planned sales $50,000, planned end-of-month stock $30,000, planned reductions $2,000, and beginning stock $28,000 give planned purchases of:','["$26,000", "$54,000", "$110,000", "$50,000"]'::jsonb,1,'50+30+2-28 = 54.','original'),
('127.263.d.6.C',3,'The product life cycle stage with the fastest rise in sales is:','["Introduction", "Decline", "Growth", "Maturity"]'::jsonb,2,'Sales climb quickly.','original'),
('127.263.d.6.C',4,'A retailer should mark down items in the decline stage to:','["Order more", "Raise prices", "Stop selling all goods", "Clear inventory before it becomes stale"]'::jsonb,3,'Clearance frees space.','original'),
('127.263.d.6.D',3,'A store that wants a $20,000 profit goal must base its budget on:','["Expected sales and costs", "Hopes only", "Last week''s weather", "Guesses"]'::jsonb,0,'Budgets come from goals.','original'),
('127.263.d.6.D',4,'A retailer expects $200,000 sales and wants a 10% profit. Allowable total costs are:','["$220,000", "$180,000", "$200,000", "$20,000"]'::jsonb,1,'200,000 x 0.9.','original'),
('127.263.d.7.A',3,'A purchase order is a document that:','["Sets prices for customers", "Records a return", "Authorizes a vendor to ship specified goods", "Lists employee hours"]'::jsonb,2,'It is a buying instruction.','original'),
('127.263.d.7.A',4,'Before paying a vendor, a retailer compares the purchase order, the invoice, and the:','["Newspaper", "Ad copy", "Menu", "Receiving report"]'::jsonb,3,'Three-way match.','original'),
('127.263.d.7.B',3,'Proper inventory management includes ordering, receiving, storing, and:','["Protecting the stock", "Ignoring it", "Hiding it", "Misplacing it"]'::jsonb,0,'Care for goods.','original'),
('127.263.d.7.B',4,'Storing fast-selling items near the shipping door helps to:','["Slow sales", "Speed picking and restocking", "Hide the items", "Raise rent"]'::jsonb,1,'Efficient layout.','original'),
('127.263.d.7.C',3,'A perpetual inventory system updates stock counts:','["Only at year end", "Never", "Continuously as sales occur", "Once a decade"]'::jsonb,2,'Real time.','original'),
('127.263.d.7.C',4,'A periodic inventory system determines stock by:','["Estimating by weight", "Ignoring counts", "Scanning every sale live", "Taking a physical count at set times"]'::jsonb,3,'Counts at intervals.','original'),
('127.263.d.7.D',3,'Cost of goods sold of $120,000 and average inventory of $30,000 give a stock turnover of:','["4", "0.25", "90", "150"]'::jsonb,0,'120,000/30,000 = 4.','original'),
('127.263.d.7.D',4,'A low stock turnover rate suggests the retailer may be holding:','["No inventory", "Too much slow-moving inventory", "Too little cash flow need", "Perfect stock"]'::jsonb,1,'Slow turnover ties up money.','original'),
('127.263.d.8.A',3,'Uncontrollable factors that affect pricing include competition and:','["The sign font", "The cashier''s name", "The state of the economy", "The store''s color"]'::jsonb,2,'External forces.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
